#ifndef REMIX_LEVEL_H
#define REMIX_LEVEL_H

#include "ultra64.h"

struct GameState;
struct PlayState;

// Web Remix new levels (src/code/z_remix_level.c). The levels themselves are generated by
// tools/remix/make_level.py into assets/scenes/remix/.

// Scene draw config of the Ancient Plateau (SDC_REMIX_ANCIENT): glow pulses, flowing circuit light and the
// Spire's moving parts, fed to the room's display lists through segments 0x08-0x0D.
void RemixLevel_DrawConfigAncient(struct PlayState* play);

// Sends Link to the Ancient Plateau from anywhere in the game.
void RemixLevel_GoToAncient(struct PlayState* play);

// "Boot straight into the new level": the website sets `mode` in the ROM it hands to the emulator (it finds
// the struct by its magic). The console logo screen then starts a test save in the Ancient Plateau instead of
// going to the title screen.
typedef struct RemixBootConfig {
    /* 0x00 */ char magic[8]; // "RMXBOOT1"
    /* 0x08 */ u8 mode;       // 0: normal boot, 1: Ancient Plateau as adult Link
    /* 0x09 */ u8 pad[7];
} RemixBootConfig;

extern RemixBootConfig gRemixBootConfig;

s32 RemixBoot_IsRequested(void);
void RemixBoot_Start(struct GameState* gameState);

#endif
